export const code = async (inputs) => {
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (key, vars) => {
    let s = String(texts[key] === undefined || texts[key] === null ? key : texts[key]);
    if (vars) Object.keys(vars).forEach((k) => { s = s.split('{' + k + '}').join(String(vars[k])); });
    return s;
  };
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const parseIso = (s) => Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
  const TZ = 'Asia/Tashkent';
  const dateFmt = new Intl.DateTimeFormat('ru-RU', { timeZone: TZ, day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
  const fmt = (iso) => {
    if (!iso) return '';
    const ms = parseIso(iso);
    return isFinite(ms) ? dateFmt.format(new Date(ms)) : '';
  };
  const cb = String(inputs.callbackData === undefined || inputs.callbackData === null ? '' : inputs.callbackData);
  const tab = cb === 'ev:list:past' ? 'past' : 'upcoming';
  const nowMs = Date.now();
  const rows = arr(inputs.eventRecords).map(flat)
    .filter((r) => String(r.status || '') === 'published')
    .sort((a, b) => parseIso(a.starts_at) - parseIso(b.starts_at));
  const isPast = (r) => {
    const endMs = parseIso(r.ends_at || r.starts_at || '');
    return isFinite(endMs) ? endMs <= nowMs : false;
  };
  const list = tab === 'past' ? rows.filter(isPast) : rows.filter((r) => !isPast(r));
  const lines = [t(tab === 'past' ? 'events.list.past_title' : 'events.list.upcoming_title')];
  if (list.length === 0) {
    lines.push(t(tab === 'past' ? 'events.list.empty_past' : 'events.list.empty_upcoming'));
  } else {
    list.forEach((r) => lines.push(t('events.list.item', { title: r.title || '', when: fmt(r.starts_at) })));
  }
  return {
    text: lines.join('\n\n'),
    reply_markup: { inline_keyboard: [[
      { text: t('events.list.btn.upcoming'), callback_data: 'ev:list:upcoming' },
      { text: t('events.list.btn.past'), callback_data: 'ev:list:past' }
    ]] }
  };
};
